            "code": "from contextlib import contextmanager\n\n@contextmanager\ndef temporary_mode(settings, value):\n    old = settings['mode']\n    settings['mode'] = value\n    print('настроено')\n    try:\n        yield settings\n    finally:\n        settings['mode'] = old\n        print('восстановлено')\n\nconfig = {'mode': 'normal'}\nmanager = temporary_mode(config, 'safe')\nprint('менеджер создан', config['mode'])\ntry:\n    with manager as inside:\n        print(inside is config, config['mode'])\n        raise ValueError('стоп')\nexcept ValueError:\n    print('ошибка снаружи')\nprint(config)",
