            "code": "from contextlib import ExitStack\n\nclass Step:\n    def __init__(self, name, broken=False):\n        self.name, self.broken = name, broken\n    def __enter__(self):\n        print('вход', self.name)\n        if self.broken:\n            raise ValueError('вход не завершён')\n        return self\n    def __exit__(self, *args):\n        print('выход', self.name)\n        return False\n\ntry:\n    with ExitStack() as stack:\n        for name in ['A', 'B', 'C']:\n            stack.enter_context(Step(name, broken=name == 'C'))\n        print('все вошли')\nexcept ValueError:\n    print('ошибка входа')",
