            "code": "from dataclasses import dataclass, field\n\n@dataclass\nclass Project:\n    name: str\n    tags: list[str] = field(default_factory=list)\n\na, b = Project('A'), Project('B')\na.tags.append('python')\nprint(a.tags, b.tags)\nshared = []\nx, y = Project('X', shared), Project('Y', shared)\nx.tags.append('общий')\nprint(y.tags)\nprint(x.tags is y.tags)",
            "output": "['python'] []\n['общий']\nTrue",
