            "code": "class AppError(Exception):\n    pass\n\nclass InputError(AppError):\n    pass\n\ndef process(broken):\n    try:\n        if broken:\n            raise InputError('неверные данные')\n    except InputError:\n        print('конкретный обработчик')\n    except AppError:\n        print('общий обработчик')\n    else:\n        print('успех')\n    finally:\n        print('завершение')\n\nprocess(False)\nprocess(True)",
